svg.script:
(function() {
  const svg = document.getElementById('svgApp');
  const listGroup = document.getElementById('list');
  const input = document.getElementById('listInput');
  const addBtn = document.getElementById('addBtn');
  const exportBtn = document.getElementById('exportBtn');
  const dataStore = document.getElementById('dataStore');

  const DATA_ID_ROOT = 'dataStore';

  if (!dataStore) {
    desc = document.createElementNS(svg.namespaceURI, 'desc');
    desc.id = 'dataStore';
    svg.appendChild(desc);
  }

  const merged = readData();
  writeData(merged);

  function readData() {
    let fileData = [];
    try {
      const desc = document.getElementById('dataStore');
      if (desc && desc.textContent) {
        const parsed = JSON.parse(desc.textContent);
        if (Array.isArray(parsed)) {
          fileData = parsed;
        }
      }
    } catch (e) { }

    let localData = [];
    try {
      const raw = localStorage.getItem(DATA_ID_ROOT);
      if (raw) {
        localData = JSON.parse(raw);
      }
    } catch (e) { console.warn('Failed to read localStorage', e); }

    const merged = [...fileData];
    localData.forEach(item => {
      if (!merged.some(i => i.text === item.text && i.created === item.created)) {
        merged.push(item);
      }
    });

    return merged;
  }

  function writeData(items) {
    try {
      localStorage.setItem(DATA_ID_ROOT, JSON.stringify(items));
    } catch (e) { }

    try {
      const desc = document.getElementById('dataStore');
      if (desc) {
        desc.textContent = JSON.stringify(items);
      }
    } catch (e) { }
  }

  function render() {
    const items = readData();
    while (listGroup.firstChild) listGroup.removeChild(listGroup.firstChild);

    const rowH = 40;
    items.forEach((it, i) => {
      const y = i * (rowH + 8);
      const g = document.createElementNS(svg.namespaceURI, 'g');
      g.setAttribute('transform', `translate(0, ${y})`);
      g.setAttribute('data-index', i);

      const bg = document.createElementNS(svg.namespaceURI, 'rect');
      bg.setAttribute('x', 0);
      bg.setAttribute('y', 0);
      bg.setAttribute('width', 676);
      bg.setAttribute('height', rowH);
      bg.setAttribute('rx', 6);
      bg.setAttribute('fill', i % 2 === 0 ? '#fff' : '#fcfcfc');
      bg.setAttribute('stroke', '#eee');
      g.appendChild(bg);

      const cb = document.createElementNS(svg.namespaceURI, 'rect');
      cb.setAttribute('x', 8);
      cb.setAttribute('y', 8);
      cb.setAttribute('width', 24);
      cb.setAttribute('height', 24);
      cb.setAttribute('rx', 4);
      cb.setAttribute('class', 'checkbox btn');
      cb.addEventListener('click', (ev) => {
        ev.stopPropagation();
        toggleItem(i);
      });
      g.appendChild(cb);

      if (it.done) {
        const check = document.createElementNS(svg.namespaceURI, 'text');
        check.setAttribute('x', 20);
        check.setAttribute('y', 26);
        check.setAttribute('text-anchor', 'middle');
        check.textContent = '✓';
        check.setAttribute('fill', '#2c7');
        check.setAttribute('font-size', 16);
        g.appendChild(check);
      }

      const t = document.createElementNS(svg.namespaceURI, 'text');
      t.setAttribute('x', 44);
      t.setAttribute('y', 25);
      t.setAttribute('class', 'listItemLabel');
      t.textContent = it.text;
      if (it.done) t.setAttribute('fill', '#999');
      g.appendChild(t);

      const del = document.createElementNS(svg.namespaceURI, 'text');
      del.setAttribute('x', 660);
      del.setAttribute('y', 25);
      del.setAttribute('class', 'del btn');
      del.textContent = '✖';
      del.addEventListener('click', (ev) => {
        ev.stopPropagation();
        deleteItem(i);
      });
      g.appendChild(del);

      const arrowX = 620;
      const arrowY = 24;

      const up = document.createElementNS(svg.namespaceURI, 'text');
      up.setAttribute('x', arrowX);
      up.setAttribute('y', arrowY);
      up.setAttribute('class', 'btn');
      up.setAttribute('font-size', 16);
      up.setAttribute('text-anchor', 'middle');
      up.textContent = '▲';
      up.addEventListener('click', (ev) => {
        ev.stopPropagation();
        moveItem(i, -1);
      });
      g.appendChild(up);

      const down = document.createElementNS(svg.namespaceURI, 'text');
      down.setAttribute('x', arrowX + 20);
      down.setAttribute('y', arrowY);
      down.setAttribute('class', 'btn');
      down.setAttribute('font-size', 16);
      down.setAttribute('text-anchor', 'middle');
      down.textContent = '▼';
      down.addEventListener('click', (ev) => {
        ev.stopPropagation();
        moveItem(i, 1);
      });
      g.appendChild(down);

      listGroup.appendChild(g);
    });
  }

  function addItem(text) {
    if (!text || !text.trim()) {
      return;
    }

    const items = readData();
    items.unshift({ text: text.trim(), done: false, created: Date.now() });
    writeData(items);
    render();
    input.value = '';
  }

  function toggleItem(index) {
    const items = readData();
    if (!items[index]) {
      return;
    }

    items[index].done = !items[index].done;
    writeData(items);
    render();
  }

  function deleteItem(index) {
    let items = readData();
    items = items.filter((_, i) => i !== index);
    writeData(items);
    render();
  }

  function moveItem(index, delta) {
    const items = readData();
    const newIndex = index + delta;
    if (newIndex < 0 || newIndex >= items.length) {
      return;
    }

    [items[index], items[newIndex]] = [items[newIndex], items[index]];
    writeData(items);
    render();
  }

  function getSvgFileName() {
    try {
      const path = window.location.pathname;
      const name = path.split('/').pop();
      return name || 'export.svg';
    } catch (e) {
      return 'export.svg';
    }
  }

  function exportSVG() {
    const serializer = new XMLSerializer();
    const source = serializer.serializeToString(svg);
    const blob = new Blob([source], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);

    const originalName = getSvgFileName();

    const a = document.createElementNS("http://www.w3.org/1999/xhtml", "a");
    a.href = url;
    a.download = originalName;
    a.dispatchEvent(new MouseEvent("click"));

    URL.revokeObjectURL(url);
  }

  addBtn.addEventListener('click', () => addItem(input.value));
  exportBtn.addEventListener('click', exportSVG);
  input.addEventListener('keydown', (ev) => {
    if (ev.key === 'Enter') {
      addItem(input.value);
    }
  });

  if (!localStorage.getItem(DATA_ID_ROOT)) {
    writeData([]);
  }
  try {
    const desc = document.getElementById('dataStore');
    if (desc && desc.textContent) {
      const parsed = JSON.parse(desc.textContent);
      if (Array.isArray(parsed)) {
        writeData(parsed);
      }
    }
  } catch (e) { }

  render();
})();
